#include <bits/stdc++.h>
using namespace std;

// Models CMake usage-requirement propagation: PUBLIC/INTERFACE reach consumers.
enum Kind { PUBLIC, PRIVATE, INTERFACE };
struct Edge { string to; Kind kind; };
map<string, vector<Edge>> deps;

// Compile requirements a target "sees" from dependency d: its own PUBLIC/INTERFACE
// edges propagate onward; PRIVATE edges stop here.
void collect(const string& t, set<string>& out) {
    for (auto& e : deps[t]) {
        out.insert(e.to);
        for (auto& e2 : deps[e.to])
            if (e2.kind != PRIVATE) { out.insert(e2.to); collect(e2.to, out); }
    }
}

int main() {
    deps["app"]   = {{"net", PRIVATE}};
    deps["net"]   = {{"fmt", PUBLIC}, {"zlib", PRIVATE}};
    deps["fmt"]   = {};
    deps["zlib"]  = {};
    cout << "net -> fmt (PUBLIC), net -> zlib (PRIVATE), app -> net (PRIVATE)\n";
    set<string> seen;
    collect("app", seen);
    cout << "app compiles with headers of:";
    for (auto& s : seen) cout << ' ' << s;
    cout << "\n";
    cout << "zlib visible to app? " << (seen.count("zlib") ? "yes" : "no") << "\n";
}

#include <bits/stdc++.h>
using namespace std;

// Decide whether an object file must be rebuilt, like Make/Ninja do.
struct File { int mtime; };  // pretend modification time

int main() {
    map<string, File> files = {
        {"main.cpp", {10}}, {"util.h", {30}}, {"main.o", {20}}, {"util.o", {35}}, {"util.cpp", {5}}
    };
    // object -> inputs (source plus headers from the .d dependency file)
    map<string, vector<string>> inputs = {
        {"main.o", {"main.cpp", "util.h"}},
        {"util.o", {"util.cpp", "util.h"}},
    };
    for (auto& [obj, ins] : inputs) {
        bool rebuild = false;
        for (auto& in : ins)
            if (files[in].mtime > files[obj].mtime) {  // newer input => stale
                cout << obj << ": " << in << " (" << files[in].mtime
                     << ") is newer than " << obj << " (" << files[obj].mtime << ")\n";
                rebuild = true;
            }
        cout << obj << (rebuild ? " -> REBUILD" : " -> up to date") << "\n";
    }
    // If util.h were missing from the .d file, main.o would never be rebuilt on a header edit.
}

#include <bits/stdc++.h>
using namespace std;

// Build graph: each job has a duration (seconds) and prerequisites.
// Wall time with unlimited cores = critical path (longest chain).
int main() {
    vector<string> name = {"gen", "a.o", "b.o", "c.o", "d.o", "lib", "link"};
    vector<int> cost    = {  20,    10,    30,    10,    10,     5,     60};
    vector<vector<int>> pre = {{}, {0}, {0}, {0}, {0}, {1, 2, 3, 4}, {5}};
    int n = name.size(), total = 0;
    vector<int> finish(n);
    for (int i = 0; i < n; i++) {          // jobs are listed in dependency order
        int start = 0;
        for (int p : pre[i]) start = max(start, finish[p]);
        finish[i] = start + cost[i];       // earliest finish time
        total += cost[i];
        cout << name[i] << " finishes at " << finish[i] << "s\n";
    }
    cout << "1 core: " << total << "s\n";
    cout << "infinite cores: " << *max_element(finish.begin(), finish.end()) << "s (critical path)\n";
}

#include <bits/stdc++.h>
using namespace std;

// Pimpl: callers only see one pointer, so the private layout can change freely.
class WidgetV1 {
    struct Impl { int id = 7; };
    unique_ptr<Impl> p = make_unique<Impl>();
public:
    int id() const { return p->id; }
};
class WidgetV2 {                 // new release adds private fields
    struct Impl { int id = 7; double scale = 1.5; string label = "x"; };
    unique_ptr<Impl> p = make_unique<Impl>();
public:
    int id() const { return p->id; }
};
// Without pimpl, adding members changes sizeof and breaks compiled callers.
struct PlainV1 { int id; };
struct PlainV2 { int id; double scale; };

int main() {
    cout << "pimpl  v1 size: " << sizeof(WidgetV1) << "\n";
    cout << "pimpl  v2 size: " << sizeof(WidgetV2) << "\n";
    cout << "plain  v1 size: " << sizeof(PlainV1) << "\n";
    cout << "plain  v2 size: " << sizeof(PlainV2) << "\n";
    cout << "pimpl ids: " << WidgetV1().id() << " " << WidgetV2().id() << "\n";
}
